create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- helper: updated_date auto-touch (แทน behaviour ของ Base44)
-- ---------------------------------------------------------------------------
create or replace function public.touch_updated_date() returns trigger
language plpgsql as $$ begin new.updated_date := now(); return new; end $$;

-- ===========================================================================
-- profiles — แทน built-in User entity ของ Base44 (ผูก 1:1 กับ auth.users)
-- ===========================================================================
create table if not exists public.profiles (
  id          uuid primary key references auth.users(id) on delete cascade,
  email       text not null unique,
  full_name   text,
  created_date timestamptz not null default now(),
  updated_date timestamptz not null default now(),
  employee_id              text,  -- รหัสพนักงาน (Auto-generated)
  payroll_code             text,  -- รหัสพนักงานจากโปรแกรมเงินเดือน (สำหรับ join ข้อมูล OT) — คนละชุดกับ employee_id
  "role"                   text default 'staff',  -- ตำแหน่งในระบบ
  nickname                 text,  -- ชื่อเล่น
  initials                 text,  -- ชื่อย่อ
  departments              jsonb,  -- แผนกที่สังกัด (หลายแผนกได้)
  department               text,  -- แผนกหลัก
  position                 text,  -- ตำแหน่งงาน เช่น หัวหน้าทีม, เจ้าหน้าที่บัญชี
  username                 text,  -- Username สำหรับแสดงผล
  phone                    text,  -- เบอร์โทร
  max_tasks                numeric default 10,  -- จำนวนงานสูงสุดที่รับได้พร้อมกัน (Capacity)
  hourly_cost              numeric default 0,  -- ต้นทุนต่อชั่วโมงของพนักงาน (บาท) — ใช้สำหรับคำนวณ Staff Cost Report
  hire_date                date,  -- วันเริ่มงาน (สำหรับคำนวณ tenure ใน Talent Matrix)
  user_status              text default 'active',  -- สถานะการใช้งาน
  theme                    text default 'default',
  notification_email       boolean default true,
  notification_line        boolean default true,
  menu_permissions         jsonb,  -- เมนูที่สามารถเข้าถึงได้
  last_modified_by         text,  -- ผู้แก้ไขล่าสุด
  promotion_watch          boolean default false,  -- ติดตามเพื่อพิจารณาเลื่อนตำแหน่ง
  promotion_watch_note     text,  -- บันทึกเหตุผลการติดตามเลื่อนตำแหน่ง
  _placeholder boolean default null
);

alter table public.profiles drop constraint if exists profiles_role_chk;
alter table public.profiles add constraint profiles_role_chk
  check ("role" is null or "role" in ('admin', 'management', 'manager', 'super_supervisor', 'staff'));
alter table public.profiles drop constraint if exists profiles_department_chk;
alter table public.profiles add constraint profiles_department_chk
  check (department is null or department in ('management', 'accounting', 'consulting', 'audit', 'billing', 'it'));
alter table public.profiles drop constraint if exists profiles_user_status_chk;
alter table public.profiles add constraint profiles_user_status_chk
  check (user_status is null or user_status in ('active', 'inactive'));
alter table public.profiles drop constraint if exists profiles_theme_chk;
alter table public.profiles add constraint profiles_theme_chk
  check (theme is null or theme in ('default', 'emerald', 'purple', 'rose', 'dark'));

-- helper: อ่าน role ของผู้ใช้ปัจจุบันจาก profiles
create or replace function public.current_app_role() returns text
language sql stable security definer set search_path = '' as $$
  select role from public.profiles where id = auth.uid()
$$;

-- helper: email ของผู้ใช้ปัจจุบัน (โค้ดเดิมเทียบ created_by กับ email)
create or replace function public.current_email() returns text
language sql stable security definer set search_path = '' as $$
  select email from public.profiles where id = auth.uid()
$$;

drop trigger if exists trg_profiles_touch on public.profiles;
create trigger trg_profiles_touch before update on public.profiles
  for each row execute function public.touch_updated_date();

-- สร้าง profile อัตโนมัติเมื่อมี auth user ใหม่
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, email, full_name)
  values (new.id, new.email, coalesce(new.raw_user_meta_data->>'full_name', new.email))
  on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

