-- ===========================================================================
-- Customer  (40 fields)
-- ===========================================================================
create table if not exists public.customer (
  id            text primary key default ('e' || replace(gen_random_uuid()::text, '-', '')),
  created_date  timestamptz not null default now(),
  updated_date  timestamptz not null default now(),
  created_by    text default public.current_email(),   -- Base44 เก็บเป็น email
  created_by_id uuid default auth.uid(),
  customer_code                text,  -- รหัสลูกค้า (Auto Gen)
  company_name                 text not null,  -- ชื่อลูกค้า / บริษัท
  company_name_en              text,  -- ชื่อบริษัท (อังกฤษ)
  tax_id                       text,  -- เลข TAX ID 13 หลัก
  branch_code                  text,  -- เลขสาขา เช่น 00000 = สำนักงานใหญ่
  address                      text,  -- ที่อยู่ลูกค้า
  customer_group               text default 'sme',  -- กลุ่มลูกค้า
  work_group                   text,  -- กลุ่มงาน
  departments                  jsonb,  -- แผนกรับผิดชอบ (หลายแผนก)
  supervisor                   text,  -- หัวหน้าดูแล (email)
  supervisor_name              text,  -- ชื่อหัวหน้าดูแล
  primary_officer              text,  -- เจ้าหน้าที่หลัก (email)
  primary_officer_name         text,  -- ชื่อเจ้าหน้าที่หลัก
  contact_person               text,  -- ชื่อผู้ติดต่อ
  contact_email                text,  -- อีเมลผู้ติดต่อ
  contact_phone                text,  -- เบอร์โทรผู้ติดต่อ
  contact_emails               jsonb,  -- ผู้ติดต่อหลายคน
  line_id                      text,  -- Line ID
  line_group_id                text,  -- LINE Group ID สำหรับส่งแจ้งเตือนเข้ากลุ่มลูกค้า
  services                     jsonb,  -- ประเภทบริการที่ใช้
  obligations                  jsonb,  -- ภาระผูกพันที่ ACC ต้องดำเนินการ
  fiscal_year_end              text,  -- วันสิ้นรอบบัญชี เช่น 12-31
  peak_package                 text default 'none',  -- Peak Account Package
  peak_license_start           date,
  peak_license_end             date,
  credit_term                  numeric,  -- Credit Term (วัน)
  monthly_fee                  numeric,  -- ค่าบริการรายเดือน (THB)
  yearly_fee                   numeric,  -- ค่าบริการรายปี (THB)
  billing_profile              jsonb,  -- Billing Profile
  referrer_id                  text,  -- ID ผู้แนะนำ (ref Referrer)
  referrer_name                text,  -- ชื่อผู้แนะนำ
  referral_commission_pct      numeric,  -- % ค่าแนะนำ (เช่น 5 = 5%)
  status                       text default 'active',
  assigned_team                jsonb,  -- ทีมที่ดูแล (user emails)
  notes                        text,  -- หมายเหตุ
  delete_requested             boolean default false,  -- มีคำขอลบอยู่หรือไม่
  delete_requested_by          text,  -- email ผู้ขอลบ
  delete_requested_by_name     text,  -- ชื่อผู้ขอลบ
  delete_requested_at          text,  -- วันเวลาที่ขอลบ
  delete_reason                text,  -- เหตุผลที่ขอลบ
  _placeholder boolean default null
);

