  delete_requested_by_name     text,  -- ชื่อผู้ขอลบ
  delete_requested_at          text,  -- วันเวลาที่ขอลบ
  delete_reason                text,  -- เหตุผลที่ขอลบ
  _placeholder boolean default null
);

