  direction                    text default 'incoming',
  file_url                     text,
  is_read                      boolean default false,
  replied_by                   text,
  reply_to_id                  text,  -- ID ของข้อความที่ตอบกลับ
  customer_id                  text,
  customer_name                text,
  chat_type                    text default 'user',  -- ประเภทแชท: user = ส่วนตัว, group = กลุ่ม
  drive_saved                  boolean default false,  -- ไฟล์ถูก save ไป Google Drive สำเร็จแล้วหรือยัง
  drive_retry_count            numeric default 0,  -- จำนวนครั้งที่ retry save ไป Drive
  request_type                 text,  -- ประเภทคำขอที่ระบบจับได้
  is_actionable                boolean default false,  -- น่าจะเป็นคำสั่งงานที่ต้องดำเนินการ
  has_statutory_deadline       boolean default false,  -- คำขอที่มีกำหนดตามกฎหมาย (ต้องรีบ)
  auto_priority                text,  -- ความสำคัญที่ระบบประเมิน
  triage_status                text default 'new',  -- สถานะการคัดกรอง
  task_id                      text,  -- รหัส Task ที่สร้างจากข้อความนี้ (ผูกกลับ)
  multi_request                boolean default false,  -- มีหลายคำขอในข้อความเดียว
  needs_review                 boolean default false,  -- พบคำปฏิเสธ/กำกวม ต้องให้คนตรวจก่อน
  dismissed_by                 text,
  dismissed_at                 text,  -- ISO datetime
  dismiss_reason               text,
  _placeholder boolean default null
);

