  completed_date               date,  -- วันที่เสร็จ
  waiting_client_since         text,  -- ISO datetime ที่เริ่มรอลูกค้า (ใช้คำนวณ due date adjustment)
  waiting_client_days          numeric default 0,  -- จำนวนวันรวมที่รอลูกค้า (สะสม)
  reviewer_email               text,  -- email ผู้ตรวจสอบ (Super Supervisor/Manager)
  reviewer_name                text,  -- ชื่อผู้ตรวจสอบ
  reviewed_date                date,  -- วันที่ตรวจสอบ
  review_deadline              date,  -- กำหนดหัวหน้าตรวจ (auto = due_date + 2 วันทำการ)
  review_status                text,  -- ผลการตรวจสอบ
  review_note                  text,  -- หมายเหตุจาก reviewer (เหตุผลที่ reject)
  checklist                    jsonb,  -- รายการตรวจสอบ
  findings                     jsonb,  -- ปัญหาที่เจอ (Findings)
  is_recurring                 boolean default false,  -- งานประจำ
  recurring_type               text,  -- ประเภทงานประจำ
  template_id                  text,  -- รหัสเทมเพลต
  attachments                  jsonb,  -- ไฟล์แนบ
  comments                     jsonb,
  due_date_change_count        numeric default 0,  -- จำนวนครั้งที่เปลี่ยน due date
  due_date_change_history      jsonb,  -- ประวัติการเปลี่ยน due date
  pending_due_change           jsonb,  -- คำขอเลื่อน due date ที่รออนุมัติ (null ถ้าไม่มี)
  rework_count                 numeric default 0,  -- จำนวนครั้งที่ถูก reject (major/critical)
  rework_count_weighted        numeric default 0,  -- คะแนนถ่วงน้ำหนัก rework (minor=0.5, major=1, critical=2)
  first_time_right             boolean,  -- true ถ้า approved ครั้งแรกโดยไม่เคยถูก reject
  last_submitted_at            text,  -- ISO datetime ตอน submit for review ล่าสุด
  submission_cycles            jsonb,  -- ประวัติทุก review cycle
  source_channel               text default 'manual',  -- ช่องทางที่มาของงาน
  source_message_id            text,  -- รหัส LineMessage ต้นทาง
  source_line_user_id          text,  -- chat key ของ LINE ต้นทาง (group id หรือ user id)
  auto_created                 boolean default false,  -- งานที่ระบบสร้างให้อัตโนมัติ
  _placeholder boolean default null
);

