  name                         text not null,  -- ชื่อ task
  description                  text,
  service_type                 text not null,
  department                   text,
  recurring_type               text default 'monthly' not null,  -- ความถี่งานประจำ
  applicable_months            jsonb,  -- เดือนที่ใช้งาน (1-12) ถ้าไม่ระบุ = ทุกเดือน
  due_date_rule                numeric default 15,  -- วันที่ครบกำหนดของเดือน เช่น 15 = วันที่ 15 ของเดือน
  default_priority             text default 'medium',
  default_status               text default 'pending',  -- สถานะเริ่มต้นของ task ที่สร้าง
  default_owner_type           text default 'from_customer',  -- กำหนดผู้รับผิดชอบจาก customer profile หรือระบุเอง
  default_owner                text,  -- email ผู้รับผิดชอบเริ่มต้น (ใช้เมื่อ default_owner_type = specific_user)
  default_owner_name           text,
  default_checklist            jsonb,
  estimated_days               numeric,  -- จำนวนวันที่คาดว่าจะใช้
  status                       text default 'active',
  _placeholder boolean default null
);

