-- ===========================================================================
create table if not exists public.tax_deadline (
  id            text primary key default ('e' || replace(gen_random_uuid()::text, '-', '')),
  created_date  timestamptz not null default now(),
  updated_date  timestamptz not null default now(),
  created_by    text default public.current_email(),   -- Base44 เก็บเป็น email
  created_by_id uuid default auth.uid(),
  tax_type                     text not null,  -- ประเภทภาษี/เงินสมทบ
  tax_label                    text not null,  -- ชื่อแสดงผล เช่น 'ภ.ง.ด.1', 'ภ.พ.30', 'ประกันสังคม'
  for_month                    numeric not null,  -- เดือนที่เป็นรอบภาษี (1-12) หรือ 0 สำหรับงานรายปี
  for_year                     numeric not null,  -- ปี ค.ศ. ของรอบภาษี
  deadline                     date not null,  -- วันกำหนดยื่นออนไลน์ (หลังเช็ควันหยุดแล้ว)
  original_day                 numeric,  -- วันที่กำหนดเดิม (ก่อนเช็ควันหยุด) เช่น 15, 23, 25
  was_shifted                  boolean default false,  -- วันที่ถูกเลื่อนจากวันหยุดหรือไม่
  shift_reason                 text,  -- เหตุผลที่เลื่อน เช่น 'ตรงวันเสาร์', 'วันหยุดสงกรานต์'
  category                     text,  -- หมวด: ภาษีหัก ณ ที่จ่าย, VAT, ธุรกิจเฉพาะ, ประกันสังคม, ภาษีนิติบุคคลรายปี, งานย
  notes                        text,
  status                       text default 'active',
  generated_by                 text,
  _placeholder boolean default null
);

