  approved_at                  text,  -- วันเวลาอนุมัติ (ISO datetime)
  rejected_at                  text,  -- วันเวลาตีกลับ (ISO datetime)
  rejection_note               text,  -- เหตุผลที่ตีกลับ
  cancelled_at                 text,  -- วันเวลายกเลิก (ISO datetime)
  cancellation_note            text,  -- เหตุผลที่ยกเลิก
  source_batch_id              text,  -- ref TaxQA_IngestionBatch ID
  filed_ref                    text,  -- เลขอ้างอิงการยื่น เช่น PND53-202604
  filed_at                     text,  -- วันเวลายืนยันยื่น (ISO datetime)
  flag_count                   numeric default 0,  -- จำนวน exception flags
  line_count                   numeric default 0,  -- จำนวนบรรทัดรายการ
