-- TaxQA_LineItem  (29 fields)
-- ===========================================================================
create table if not exists public.tax_qa_line_item (
  id            text primary key default ('e' || replace(gen_random_uuid()::text, '-', '')),
  created_date  timestamptz not null default now(),
  updated_date  timestamptz not null default now(),
  created_by    text default public.current_email(),   -- Base44 เก็บเป็น email
  created_by_id uuid default auth.uid(),
  filing_id                    text not null,  -- ref TaxQA_Filing ID
  seq_in_file                  numeric,  -- ลำดับในไฟล์ (ซ้ำได้ ห้ามใช้เป็น key)
  ref_doc_1                    text,  -- เลขที่เอกสารอ้างอิง 1
  ref_doc_2                    text,  -- เลขที่เอกสารอ้างอิง 2
  branch                       text,  -- สาขา/สำนักงานใหญ่
  raw_status                   text,  -- สถานะจากไฟล์ต้นทาง
  cert_no                      text,  -- เลขที่หนังสือรับรองหัก ณ ที่จ่าย (คีย์ group บรรทัด WHT ในใบเดียวกัน)
  pay_date                     text,  -- วันที่หัก ณ ที่จ่าย
  payee_code                   text,  -- รหัสผู้ติดต่อ
  payee_name                   text,  -- ชื่อผู้รับเงิน
  payee_tax_id                 text,  -- เลขทะเบียนผู้เสียภาษี 13 หลัก
  pnd_type                     text,  -- ประเภท ภ.ง.ด.
  income_desc                  text,  -- ประเภทเงินได้
  wht_rate                     numeric,  -- อัตราภาษี (%)
  tax_base                     numeric,  -- จำนวนเงินที่จ่าย (ฐานภาษี)
  wht_amount                   numeric,  -- ภาษีหัก ณ ที่จ่าย
  wht_condition                text,  -- เงื่อนไขการหักภาษี
  tax_invoice_no               text,  -- เลขที่ใบกำกับภาษี (VAT)
  tax_invoice_date             text,  -- วันที่ใบกำกับภาษี (VAT)
  invoice_type                 text,  -- ประเภทใบกำกับ (VAT)
  contact_code                 text,  -- รหัสผู้ติดต่อ (VAT)
  counterparty_name            text,  -- ชื่อคู่ค้า (VAT)
  counterparty_tax_id          text,  -- เลขทะเบียนผู้เสียภาษีคู่ค้า (VAT)
  exempt_amount                numeric,  -- รายการยกเว้นภาษี
  vat0_amount                  numeric,  -- รายการภาษี 0%
  vat7_base                    numeric,  -- รายการภาษี 7% (ฐาน VAT)
  vat_amount                   numeric,  -- ภาษีมูลค่าเพิ่ม
  total_incl_vat               numeric,  -- มูลค่ารวมภาษี
  vat_direction                text,  -- ภาษีขาย (output) หรือภาษีซื้อ (input)
  _placeholder boolean default null
);

alter table public.tax_qa_line_item drop constraint if exists tax_qa_line_item_vat_direction_chk;
alter table public.tax_qa_line_item add constraint tax_qa_line_item_vat_direction_chk
  check (vat_direction is null or vat_direction in ('output', 'input'));
drop trigger if exists trg_tax_qa_line_item_touch on public.tax_qa_line_item;
create trigger trg_tax_qa_line_item_touch before update on public.tax_qa_line_item
  for each row execute function public.touch_updated_date();
create index if not exists idx_tax_qa_line_item_filing_id on public.tax_qa_line_item (filing_id);
create index if not exists idx_tax_qa_line_item_payee_tax_id on public.tax_qa_line_item (payee_tax_id);
create index if not exists idx_tax_qa_line_item_counterparty_tax_id on public.tax_qa_line_item (counterparty_tax_id);

