-- TaxQA_ReviewLog  (9 fields)
-- ===========================================================================
create table if not exists public.tax_qa_review_log (
  id            text primary key default ('e' || replace(gen_random_uuid()::text, '-', '')),
  created_date  timestamptz not null default now(),
  updated_date  timestamptz not null default now(),
  created_by    text default public.current_email(),   -- Base44 เก็บเป็น email
  created_by_id uuid default auth.uid(),
  entity_name                  text not null,  -- ชื่อ entity ที่เกี่ยวข้อง
  entity_id                    text not null,  -- ID ของ entity
  action                       text not null,  -- การกระทำ เช่น approve, reject, override, submit
  actor_email                  text not null,  -- email ผู้กระทำ
  actor_name                   text,  -- ชื่อผู้กระทำ
  timestamp                    text,  -- วันเวลา (ISO datetime)
  before_value                 text,  -- ค่าก่อนเปลี่ยน (JSON string)
  after_value                  text,  -- ค่าหลังเปลี่ยน (JSON string)
  note                         text,  -- หมายเหตุ
  _placeholder boolean default null
);

drop trigger if exists trg_tax_qa_review_log_touch on public.tax_qa_review_log;
create trigger trg_tax_qa_review_log_touch before update on public.tax_qa_review_log
  for each row execute function public.touch_updated_date();
create index if not exists idx_tax_qa_review_log_entity_id on public.tax_qa_review_log (entity_id);
create index if not exists idx_tax_qa_review_log_actor_email on public.tax_qa_review_log (actor_email);

-- ===========================================================================
-- TaxQA_ValidationRule  (9 fields)
-- ===========================================================================
create table if not exists public.tax_qa_validation_rule (
  id            text primary key default ('e' || replace(gen_random_uuid()::text, '-', '')),
  created_date  timestamptz not null default now(),
  updated_date  timestamptz not null default now(),
  created_by    text default public.current_email(),   -- Base44 เก็บเป็น email
  created_by_id uuid default auth.uid(),
  rule_code                    text not null,  -- รหัสกฎ unique
  form_type                    text not null,  -- แบบภาษีที่ใช้
  description                  text not null,  -- คำอธิบายกฎ (ไทย)
  rule_category                text not null,  -- หมวดหมู่กฎ
  severity_default             text default 'warning',  -- ระดับความรุนแรงเริ่มต้น
  parameters                   jsonb,  -- พารามิเตอร์ JSON ของกฎ
  legal_reference              text,  -- อ้างอิงกฎหมาย
  active                       boolean default true,  -- เปิดใช้งานหรือไม่
  effective_date               date,  -- วันที่มีผลบังคับใช้
  _placeholder boolean default null
);

alter table public.tax_qa_validation_rule drop constraint if exists tax_qa_validation_rule_form_type_chk;
alter table public.tax_qa_validation_rule add constraint tax_qa_validation_rule_form_type_chk
  check (form_type is null or form_type in ('PND1', 'PND3', 'PND53', 'PND54', 'PP36', 'PP30', 'ALL'));
alter table public.tax_qa_validation_rule drop constraint if exists tax_qa_validation_rule_rule_category_chk;
alter table public.tax_qa_validation_rule add constraint tax_qa_validation_rule_rule_category_chk
  check (rule_category is null or rule_category in ('structural', 'rate', 'cross_form', 'continuity', 'reconciliation', 'ingestion'));
alter table public.tax_qa_validation_rule drop constraint if exists tax_qa_validation_rule_severity_default_chk;
alter table public.tax_qa_validation_rule add constraint tax_qa_validation_rule_severity_default_chk
  check (severity_default is null or severity_default in ('error', 'warning'));
drop trigger if exists trg_tax_qa_validation_rule_touch on public.tax_qa_validation_rule;
create trigger trg_tax_qa_validation_rule_touch before update on public.tax_qa_validation_rule
  for each row execute function public.touch_updated_date();

