-- ===========================================================================
create table if not exists public.tax_qa_vat_period_register (
  id            text primary key default ('e' || replace(gen_random_uuid()::text, '-', '')),
  created_date  timestamptz not null default now(),
  updated_date  timestamptz not null default now(),
  created_by    text default public.current_email(),   -- Base44 เก็บเป็น email
  created_by_id uuid default auth.uid(),
  customer_id                  text not null,  -- ref Customer ID
  customer_name                text not null,  -- ชื่อลูกค้า (denormalized)
  tax_period                   text not null,  -- งวดภาษี YYYY-MM
  version                      numeric default 1,  -- เวอร์ชัน (1=ฉบับปกติ, 2+=เพิ่มเติม)
  output_vat                   numeric default 0,  -- ภาษีขาย
  input_vat                    numeric default 0,  -- ภาษีซื้อ
  credit_brought_forward       numeric default 0,  -- เครดิตยกมา
  credit_carried_forward       numeric default 0,  -- เครดิตยกไป
  net_payable                  numeric default 0,  -- ภาษีที่ต้องชำระ (สุทธิ)
  status                       text default 'filed',  -- สถานะ
  source_filing_id             text,  -- ref TaxQA_Filing ID
  _placeholder boolean default null
);

alter table public.tax_qa_vat_period_register drop constraint if exists tax_qa_vat_period_register_status_chk;
alter table public.tax_qa_vat_period_register add constraint tax_qa_vat_period_register_status_chk
  check (status is null or status in ('filed', 'amended'));
drop trigger if exists trg_tax_qa_vat_period_register_touch on public.tax_qa_vat_period_register;
create trigger trg_tax_qa_vat_period_register_touch before update on public.tax_qa_vat_period_register
  for each row execute function public.touch_updated_date();
create index if not exists idx_tax_qa_vat_period_register_customer_id on public.tax_qa_vat_period_register (customer_id);
create index if not exists idx_tax_qa_vat_period_register_status on public.tax_qa_vat_period_register (status);
create index if not exists idx_tax_qa_vat_period_register_source_filing_id on public.tax_qa_vat_period_register (source_filing_id);

