-- ===========================================================================
-- RLS BASELINE
-- Base44 ไม่มี row-level rule ในไฟล์ entity เลย → พฤติกรรมเดิมคือ
-- 'ผู้ใช้ที่ล็อกอินแล้วเข้าถึงได้ทั้งหมด' (คุมสิทธิ์ที่ชั้น UI ด้วย menu_permissions)
-- baseline นี้จึงรักษาพฤติกรรมเดิมไว้ = authenticated เข้าถึงได้ / anon เข้าไม่ได้
-- >>> ตารางที่มีข้อมูลอ่อนไหวถูกยกเป็น policy เข้มกว่าด้านล่าง <<<
-- ===========================================================================

alter table public.profiles enable row level security;
drop policy if exists profiles_select on public.profiles;
create policy profiles_select on public.profiles for select to authenticated using (true);
drop policy if exists profiles_update_self on public.profiles;
create policy profiles_update_self on public.profiles for update to authenticated
  using (id = auth.uid() or public.current_app_role() in ('admin','management'));
drop policy if exists profiles_admin_all on public.profiles;
create policy profiles_admin_all on public.profiles for all to authenticated
  using (public.current_app_role() = 'admin') with check (public.current_app_role() = 'admin');

alter table public.announcement enable row level security;
drop policy if exists announcement_all on public.announcement;
create policy announcement_all on public.announcement for all to authenticated
  using (true) with check (true);

alter table public.app_config enable row level security;
drop policy if exists app_config_all on public.app_config;
create policy app_config_all on public.app_config for all to authenticated
  using (true) with check (true);

alter table public.audit_log enable row level security;
-- AuditLog: ข้อมูลอ่อนไหว (PDPA) — จำกัด role
drop policy if exists audit_log_ro on public.audit_log;
create policy audit_log_ro on public.audit_log for select to authenticated
  using (public.current_app_role() in ('admin','management','manager'));
drop policy if exists audit_log_rw on public.audit_log;
create policy audit_log_rw on public.audit_log for all to authenticated
  using (public.current_app_role() in ('admin','management'))
  with check (public.current_app_role() in ('admin','management'));

